class BankAccount {
    String accountHolder;
    String accountNumber;
    double balance;

    // 1. MASTER CONSTRUCTOR: All assignments and validation happen here
    BankAccount(String accountHolder, String accountNumber, double balance) {
        this.accountHolder = accountHolder;
        this.accountNumber = accountNumber;
        if (balance < 0.0) {
            this.balance = 0.0;
        } else {
            this.balance = balance;
        }
    }

    // 2. OVERLOADED: Name and account number only (opening balance defaults to 0.0)
    BankAccount(String accountHolder, String accountNumber) {
        this(accountHolder, accountNumber, 0.0); // Chains to Master
    }

    // 3. OVERLOADED: Default guest account
    BankAccount() {
        this("Guest User", "PENDING-000"); // Chains to 2-arg constructor
    }

    // Operational Methods
    void deposit(double amount) {
        if (amount > 0) {
            this.balance += amount;
        }
    }

    void displayAccount() {
        System.out.println("========================================");
        System.out.println("Account Holder: " + this.accountHolder);
        System.out.println("Account Number: " + this.accountNumber);
        System.out.println("Current Balance: $" + this.balance);
        System.out.println("========================================");
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount acc1 = new BankAccount();
        BankAccount acc2 = new BankAccount("Rahul Sharma", "ACC-1010");
        BankAccount acc3 = new BankAccount("Priya Patel", "ACC-2020", 1250.0);

        acc2.deposit(350.0);

        acc1.displayAccount();
        acc2.displayAccount();
        acc3.displayAccount();
    }
}

