class BankAccount {
    String accountHolder;
    String accountNumber;
    double balance;

    BankAccount(String accountHolder, String accountNumber, double balance) {
        this.accountHolder = accountHolder;
        this.accountNumber = accountNumber;
        this.balance = (balance < 0.0) ? 0.0 : balance;
    }

    boolean transferTo(BankAccount target, double amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            target.balance += amount;
            return true;
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount rahul = new BankAccount("Rahul", "ACC-101", 100.0);
        BankAccount priya = new BankAccount("Priya", "ACC-202", 500.0);

        boolean success = priya.transferTo(rahul, 200.0);
        System.out.println("Transfer Success: " + success + " | Rahul Balance: $" + rahul.balance + " | Priya Balance: $" + priya.balance);
    }
}
